function updateBatch(batchEdges){
  for (const [u,v,w] of batchEdges){
    // ensure undirected view if needed
    adj[u].push([v,w]);
    adj[v].push([u,w]);
  }
  for (const [u,v,w] of batchEdges){
    if (dist[v] > dist[u] + w){
      dist[v] = dist[u] + w;
      pq.push([dist[v], v]);
    }
    if (dist[u] > dist[v] + w){
      dist[u] = dist[v] + w;
      pq.push([dist[u], u]);
    }
  }
  while (!pq.isEmpty()){
    const [d, x] = pq.pop();
    if (d !== dist[x]) continue;
    for (const [y,w] of adj[x]){
      if (dist[y] > dist[x] + w){
        dist[y] = dist[x] + w;
        pq.push([dist[y], y]);
      }
    }
  }
}
```

